#include "plotting/plot_template.hpp"
#include "plotting/native_export.hpp"
#include "runtime/interpreter.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace penta;
int main(){int failures=0,checks=0;auto expect=[&](bool okay,const char* text){++checks;if(!okay){++failures;std::cerr<<text<<'\n';}};const auto directory=std::filesystem::temp_directory_path()/("penta-template-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(directory);
    try{plotting::PlotTemplate source;source.style.colors={{{.1,.2,.3}}};source.style.fontFamily="serif";source.style.fontSize=17;source.style.legendLabels={"full λ","ordered p*q"};source.style.lineStyle="dash";source.style.limits[0]=runtime::AxisLimits{-3,4};source.style.colorLimits=runtime::AxisLimits{-1,1};source.labels={"$\\alpha_1$","time λ","response","z","Unicode μ caption"};source.latex={true,false,false,false,false};const auto path=directory/"style.json";plotting::writePlotTemplate(source,path);const auto read=plotting::readPlotTemplate(path);expect(read.style==source.style&&read.labels==source.labels&&read.latex==source.latex,"Template roundtrip retains complete styles, Unicode and per-label LaTeX flags.");bool rejected=false;try{plotting::writePlotTemplate({},path);}catch(const std::exception&){rejected=true;}expect(rejected&&plotting::readPlotTemplate(path).labels==source.labels,"An existing template is preserved without explicit overwrite.");
        runtime::FigureAction plot;plot.kind=runtime::FigureActionKind::Plot;plot.dimensions=2;plot.axes={-1,-1,-1};plot.curves.push_back({{{0,1,0},{1,2,0}},"original"});runtime::FigureAction apply;apply.kind=runtime::FigureActionKind::ApplyPlotTemplate;apply.plotTemplate=std::make_shared<const plotting::PlotTemplate>(source);plotting::NativeFigureScene scene;scene.ingest({plot,apply});const auto panel=scene.panels().front();expect(panel.curves[0].points==plot.curves[0].points&&panel.style==source.style&&panel.title==source.labels[0]&&panel.latex==source.latex,"Applying a headless template preserves original samples.");
        runtime::ExecutionOptions options;options.dataDirectory=directory;options.nativeFigureExport=true;const auto result=runtime::execute("figure(1);plot([0,1],[1,2]);plotstyle(options(font_family=\"serif\",line_width=3));title(\"$p+q$\");saveplottemplate(\"language-style.json\");plotstyle(options(line_width=1));loadplottemplate(\"language-style.json\");",{},options);if(!result.ok()){for(const auto& d:result.analysis.diagnostics)std::cerr<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.message<<'\n';}expect(result.ok(),"Language can save/apply a data-only style in headless execution.");if(result.ok()){plotting::NativeFigureScene languageScene;languageScene.ingest(result.figureActions);expect(languageScene.currentTemplate().style.lineWidth==3&&languageScene.currentTemplate().labels[0]=="$p+q$","Restored language styles and labels take effect.");}
        std::ofstream(directory/"deep.json")<<std::string(40,'[')<<std::string(40,']');rejected=false;try{(void)plotting::readPlotTemplate(directory/"deep.json");}catch(const std::exception&){rejected=true;}expect(rejected,"Deep malformed input is rejected within parser depth allowance.");std::ofstream(directory/"unknown.json")<<"{\"format\":\"PentarnionPlotTemplate\",\"version\":99}";rejected=false;try{(void)plotting::readPlotTemplate(directory/"unknown.json");}catch(const std::exception&){rejected=true;}expect(rejected,"Unsupported template versions never execute or apply.");
    }catch(const std::exception& error){++failures;std::cerr<<error.what()<<'\n';}std::error_code ignored;std::filesystem::remove_all(directory,ignored);std::cout<<checks<<" template checks, "<<failures<<" failures\n";return failures?1:0;}
